package com.bhagya.qa.performance;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.Locale;
public class ReportWriter {public void write(PerformanceResult r)throws Exception{Path p=Path.of("reports");Files.createDirectories(p);String json=String.format(Locale.US,"{\n \"generatedAt\":\"%s\",\n \"scenario\":\"%s\",\n \"users\":%d,\n \"totalRequests\":%d,\n \"successfulRequests\":%d,\n \"failedRequests\":%d,\n \"durationMs\":%d,\n \"p50Ms\":%d,\n \"p95Ms\":%d,\n \"p99Ms\":%d,\n \"throughputPerSecond\":%.2f,\n \"errorRatePercent\":%.2f\n}\n",Instant.now(),r.scenario,r.users,r.totalRequests,r.successfulRequests,r.failedRequests,r.durationMs,r.p50Ms,r.p95Ms,r.p99Ms,r.throughputPerSecond,r.errorRatePercent);Files.writeString(p.resolve("summary.json"),json,StandardCharsets.UTF_8);String csv="scenario,users,totalRequests,successfulRequests,failedRequests,durationMs,p50Ms,p95Ms,p99Ms,throughputPerSecond,errorRatePercent\n"+String.format(Locale.US,"%s,%d,%d,%d,%d,%d,%d,%d,%d,%.2f,%.2f\n",r.scenario,r.users,r.totalRequests,r.successfulRequests,r.failedRequests,r.durationMs,r.p50Ms,r.p95Ms,r.p99Ms,r.throughputPerSecond,r.errorRatePercent);Files.writeString(p.resolve("requests.csv"),csv,StandardCharsets.UTF_8);String html="<!doctype html><html><head><meta charset='utf-8'><title>Performance Report</title><style>body{font-family:Arial;margin:32px;background:#f4f6fb;color:#172033}h1{color:#4934a5}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:14px}.card{background:white;padding:18px;border-radius:12px;box-shadow:0 2px 10px #0001}.v{font-size:28px;font-weight:bold;margin-top:8px}</style></head><body><h1>Performance Test Report</h1><p>Scenario: "+r.scenario+" · Generated: "+Instant.now()+"</p><div class='grid'><div class='card'>Concurrent Users<div class='v'>"+r.users+"</div></div><div class='card'>Requests<div class='v'>"+r.totalRequests+"</div></div><div class='card'>P95 Response Time<div class='v'>"+r.p95Ms+" ms</div></div><div class='card'>Throughput<div class='v'>"+String.format(Locale.US,"%.2f",r.throughputPerSecond)+" req/s</div></div><div class='card'>Error Rate<div class='v'>"+String.format(Locale.US,"%.2f%%",r.errorRatePercent)+"</div></div><div class='card'>Failed Requests<div class='v'>"+r.failedRequests+"</div></div></div><h2>Interpretation</h2><p>Compare the measured P95, error rate and throughput with a real baseline before release.</p></body></html>";Files.writeString(p.resolve("performance-report.html"),html,StandardCharsets.UTF_8);}}
